{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
const known = new Set()
const ballots = []
const ONCE = 'candidates must be declared once, before any ballot'
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  const err = (m) => fail(`error: line ${n}: ${m}`)
  if (w[0] === 'candidates') {
    if (names !== null || ballots.length) err(ONCE)
    if (w.length < 2) err('expected candidates <name>...')
    names = []
    for (const nm of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(nm)) err(`invalid candidate name ${nm}`)
      if (known.has(nm)) err(`candidate ${nm} is declared twice`)
      known.add(nm)
      names.push(nm)
    }
  } else if (w[0] === 'ballot') {
    if (names === null) err(ONCE)
    if (w.length < 3) err('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(w[1])) err('count must be a positive integer')
    const seen = new Set()
    for (const nm of w.slice(2)) {
      if (!known.has(nm)) err(`unknown candidate ${nm}`)
      if (seen.has(nm)) err(`candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    err(`unknown directive ${w[0]}`)
  }
}
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = []
const out = []
let winner = null
let nrounds = 0
for (;;) {
  nrounds++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  history.push(counts)
  const list = [...counts.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  out.push(`round ${nrounds}: ${list.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) break
  const top = list[0]
  if (top[1] * 2n > active) {
    winner = top[0]
    break
  }
  let min = list[list.length - 1][1]
  let s = list.filter(([, v]) => v === min).map(([c]) => c)
  for (let again = s.length > 1; again; ) {
    again = false
    for (const h of history) {
      const vals = s.map((c) => h.get(c))
      const m = vals.reduce((a, b) => (a < b ? a : b))
      if (vals.some((v) => v !== m)) {
        s = s.filter((c) => h.get(c) === m)
        again = s.length > 1
        break
      }
    }
  }
  s.sort()
  const elim = s[s.length - 1]
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
process.stdout.write((mode === 'rounds' ? out.join('\n') + '\n' : `rounds ${nrounds}\n`) + end + '\n')
EOF
